    fact.resize(maxN);
    fact[0] = 1;
    for (int i = 1; i < maxN; i++) {
        fact[i] = (fact[i - 1] * i) % MOD;
    }
    int n;
    long long k;
    cin >> n >> k;
    if (k >= n) {
        cout << 0 << "\n";
        return 0;
    }
    if (k == 0) {
        cout << fact[n] << "\n";
        return 0;
    }
    if (k == n - 1) {
        cout << 2LL * n << "\n";
        return 0;
    }
    int filled = (int)(n - k);
    long long chooseFilled = nCr(n, filled);
    long long total = 0;
    for (int empty = 0; empty <= filled; empty++) {
        long long choose = nCr(filled, empty);
        long long fillWays = power(filled - empty, n);
        long long val = (choose * fillWays) % MOD;
        if (empty % 2 == 1) val = (MOD - val) % MOD;
        total = (total + val) % MOD;
    }
    total = (total * chooseFilled) % MOD;
    total = (total * 2) % MOD;
    cout << total << "\n";
    return 0;
}
